def transform(grid):
    if not grid:
        return []
    if not grid[0]:
        return []

    w = len(grid[0])
    h = len(grid)

    # Determine background color (most frequent)
    counts = {}
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val not in counts:
                counts[val] = 0
            counts[val] += 1

    bg = max(counts, key=counts.get)

    output_grid = []
    for r in range(h):
        # Find the column index of the non-background object
        c_obj = -1
        for c in range(w):
            if grid[r][c] != bg:
                c_obj = c
                break

        if c_obj == -1:
            # No object found in this row, fill with background
            output_grid.append([bg] * w)
        else:
            # Determine output color based on column position
            # The rule maps the row's solid color based on which third of the grid the object is in.
            # w=6: [0,1]->2, [2,3]->4, [4,5]->3 (2-2-2 split)
            # w=15: [0-4]->2, [5-9]->4, [10-14]->3 (5-5-5 split)
            # Formula: bin = c * 3 // w
            bin_idx = (c_obj * 3) // w

            if bin_idx == 0:
                color = 2
            elif bin_idx == 1:
                color = 4
            else:
                color = 3

            # Fill the row with the determined color
            output_grid.append([color] * w)

    return output_grid
